	if(!$Keyword){$Keyword = $Target;}
			
	$Image_1 = "../Cache/".str_replace(" ", "_", $Keyword)."_0.png";
	$Image_2 = "../Cache/".str_replace(" ", "_", $Keyword)."_1.png";
	$Image_3 = "../Cache/".str_replace(" ", "_", $Keyword)."_2.png";
	$Image_4 = "../Cache/".str_replace(" ", "_", $Keyword)."_3.png";
	
	if (!file_exists($Image_1) or filemtime($Image_1) < strtotime("-5 days")) 
		{
			
			$Request	= "http://images.google.com/images?as_q=".urlencode($Keyword)."&svnum=10&hl=en&btnG=Google+Search&as_epq=&as_oq=&as_eq=&imgsz=small%7Cmedium%7Clarge%7Cxlarge&as_filetype=&imgc=&as_sitesearch=&safe=images";

			$fp			= fopen($Request, "r");					
			
			while (!feof($fp)) 
				{
					$GooglePics .= fread($fp, 1024);
				}

			fclose($fp);
			
			preg_match_all("|<img src=(/images\?q=.*?) |si", $GooglePics, $Matches);	
			
			$Matches	= array_slice($Matches[1], 0, 4);		
			
			for ($Ctr	= 0; $Ctr < 4; $Ctr++) 
				{
					$URL	= "http://www.google.com".$Matches[$Ctr];
					
					$Type	= getimagesize($URL);	

					switch($Type[2]) 
						{
							case 1:
								$Thumb = imagecreatefromgif($URL);
								break;
							case 2:
								$Thumb = imagecreatefromjpeg($URL);
								break;
							case 3:
								$Thumb = imagecreatefrompng($URL);
								break;
							case 6:
								$Thumb = imagecreatefromwbmp($URL);
								break;
						}

					ob_start();      
					
						imagepng($Thumb);
						
						$Image			= ob_get_contents();
					
					ob_end_clean();

					$fp	= fopen("../Cache/".str_replace(" ", "_", $Keyword."_".$Ctr.".png"), "wb");										
						
						fwrite($fp, $Image);
					
					fclose($fp);

				}
		}								
